import{_ as o,l as i,o as e,c as s,v as t,p as l,x as n,d as h,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"GMM 与资产定价检验","description":"","frontmatter":{"title":"GMM 与资产定价检验","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/gmm-asset-pricing.md","filePath":"quant/gmm-asset-pricing.md","lastUpdated":1789023840000}'),d={name:"quant/gmm-asset-pricing.md"};function M(E,a,c,g,S,_){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="gmm-与资产定价检验" tabindex="-1">GMM 与资产定价检验 <a class="header-anchor" href="#gmm-与资产定价检验" aria-label="Permalink to &quot;GMM 与资产定价检验&quot;">​</a></h1><div class="epigraph"><p>把模型写成一束正交条件，用这些条件的样本均值去匹配零，再按条件的长期协方差加权；过度识别的距离本身就是检验。</p><footer>—— Hansen, Large Sample Properties of Generalized Method of Moments Estimators, Econometrica, 1982</footer></div><p><a href="/quant/long-horizon-overlap">上一课</a>指出 \\(h\\) 期重叠收益让独立信息大约降到 \\(T/h\\)，必须用 Hansen–Hodrick 或 Newey–West。重叠回归已经是一个矩 \\(E[u_{t,h}x_t]=0\\)。资产定价把矩写成随机折现因子 \\(E[m_{t+1}R_{t+1}^e]=0\\)，或线性因子的 \\(E[R^e]=\\beta\\lambda\\)。Hansen 的 GMM 一次给出参数、HAC 式权重、以及过度识别的 \\(J\\) 检验。本课缺口：在 <a href="/quant/fama-macbeth">Fama–MacBeth</a> 与 <a href="/quant/grs-test">GRS</a> 之后，用同一套正交条件做估计与检验。不重推重叠窗口的 HAC 滞后。下一课 HJ 距离是这套矩的定价误差范数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>参数 \\(\\theta\\)（因子溢价、SDF 系数、效用参数）满足 \\(E[g(w_t,\\theta)]=0\\)。样本均值 \\(\\bar g(\\theta)\\)，GMM 最小化 \\(\\bar g^\\top W\\bar g\\)。最优 \\(W=S^{-1}\\)，\\(S\\) 是 \\(g_t\\) 的长期方差——正是 Newey–West 要估的对象。过度识别时，\\(\\min J\\) 渐近 \\(\\chi^2\\)，检验模型是否被矩拒绝。</p><p>问题是：资产多、矩多时 \\(S\\) 估不稳，最优 GMM 有限样本差；一阶段 \\(W=I\\) 稳但无效。资产定价常用两阶段或连续更新（CUE）。对象是<strong>矩是否成立</strong>，不是截面 \\(R^2\\)。</p><h3 id="与-fm、grs-的翻译" tabindex="-1">与 FM、GRS 的翻译 <a class="header-anchor" href="#与-fm、grs-的翻译" aria-label="Permalink to &quot;与 FM、GRS 的翻译&quot;">​</a></h3><p>线性因子、可交易因子：时间序列 \\(E[\\varepsilon_{it}]=0\\)、\\(E[\\varepsilon_{it}f_t]=0\\) 加上定价 \\(E[R_i]=\\beta_i^\\top\\lambda\\)。GMM 把 FM 两步收成一块，并自动加 Shanken 一类生成回归量修正（若把 \\(\\beta\\) 也当参数）。因子是超额收益时，\\(\\lambda=E[f]\\) 是约束，GRS 是正态有限样本版本，GMM \\(J\\) 是渐近版本。两者应同向；只报好看的那一个是选择报告。</p><p><span class="marginnote">Hansen 的 \\(J\\) 拒绝，说的是矩不成立，不是「哪个因子坏」。过度识别把所有资产的定价误差捆在一起。要看谁坏，应看定价误差向量或其 HJ 距离分解。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>估计。</strong> 选 \\(g\\)：欧拉 \\(m(\\theta)R^e\\)、或 beta 表示的误差。\\(S\\) 用 Newey–West，带宽与收益重叠一致。连续更新让 \\(W\\) 依赖 \\(\\theta\\)，小样本有时更好，数值更脆。资产 \\(N\\) 相对 \\(T\\) 大时，应减资产（组合）或用因子模型压缩，否则 \\(S\\) 不可逆。</p><p><strong>标准误。</strong> 三明治形式，已经含 HAC。聚类：若用个股面板矩，按时间聚类对应同期相关，与 FM 同一逻辑。不要对 GMM 再「只开 White」。</p><p><strong>弱识别。</strong> 因子若几乎不驱动检验资产，定价矩对 \\(\\lambda\\) 平坦，GMM 像弱工具。应看第一阶段式的因子波动与 \\(\\beta\\) 的联合，而不是只看 \\(J\\) 没拒绝（弱时 \\(J\\) 也没功效）。</p><h3 id="消费欧拉与因子-sdf" tabindex="-1">消费欧拉与因子 SDF <a class="header-anchor" href="#消费欧拉与因子-sdf" aria-label="Permalink to &quot;消费欧拉与因子 SDF&quot;">​</a></h3><p>Hansen–Singleton 的幂效用消费欧拉，矩弱、资产少时已经难估；加股票、债券后常被 \\(J\\) 拒绝。这是模型失败，不是 GMM 失败。线性 SDF \\(m=1-b^\\top f\\) 把同一装置用在可观测因子上，与 <a href="/quant/capm">CAPM</a> 的 beta 表示对偶。报告 \\(b\\) 与 \\(\\lambda\\) 的换算，避免两套系数各说各话。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>GMM 是 M 估计：解 \\(\\partial\\bar g^\\top W\\bar g/\\partial\\theta=0\\)。最优 \\(W\\) 把信息多的矩（噪声小的正交条件）加权更大。\\(J\\) 是加权定价误差的范数：模型真则 \\(\\sqrt{T}\\bar g\\) 的二次型 \\(\\to\\chi^2\\)；模型假则 \\(J\\) 随 \\(T\\) 涨。机制上，<strong>检验与估计共用同一 \\(S\\)</strong>，所以 \\(S\\) 估错会同时弄坏点和检验——小样本里这是 GMM 的主风险。</p><p>与 OLS+HAC：恰好识别、线性、矩就是 \\(x u\\) 时，GMM 退回 OLS，方差退回 Newey–West。资产定价的价值在过度识别：额外资产是额外矩，用来检验而不是只用来估。</p><p><span class="marginnote">权重矩阵 \\(W\\) 改变的是有效性与 \\(J\\) 的度量，不改变恰好识别时的点。过度识别时，不同 \\(W\\) 给出不同 \\(\\hat\\theta\\)——你在用哪组资产的误差去定义「最小」。须声明 \\(W\\)。</span></p><h3 id="有限样本纪律" tabindex="-1">有限样本纪律 <a class="header-anchor" href="#有限样本纪律" aria-label="Permalink to &quot;有限样本纪律&quot;">​</a></h3><p>\\(N=25\\) 组合、\\(T=600\\) 月、滞后 12 的 \\(S\\) 很大。仿真（用因子模型抽收益再估）应作为 \\(J\\) 的校正，尤其因子数 \\(K\\) 增加时。Lewellen–Nagel–Shanken 批评：用因子自己排序的组合做矩，GMM 会「通过」。检验资产须含模型外组合。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>非线性 SDF、习惯、递归偏好，GMM 对初值敏感，应多起点。矩条件用水平还是用工具（滞后消费、滞后收益）会改变识别，弱工具问题从 IV 课原样进来。高频矩（已实现量）的 \\(S\\) 有微观结构，不要把日频 HAC 套在 tick 矩上。</p><p>工程：先 FM/GRS 看经济幅度，再 GMM 报联合 \\(J\\) 与稳健 \\(\\lambda\\)；检验资产预登记。不要用 \\(N\\gt T\\) 的个股矩做最优 GMM。不要把 \\(J\\) 的 p=0.06 写成模型成立。下一课把定价误差用 Hansen–Jagannathan 的范数再量一次。</p>',24)),(e(),l(m,null,{default:n(()=>[p(r,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%A8%A1%E5%9E%8B%20%E2%86%92%20%E7%9F%A9%20g(%CE%B8)%3D0%22%5D%20--%3E%20G%5B%22%E6%A0%B7%E6%9C%AC%E5%9D%87%E5%80%BC%20%E1%B8%A1%22%5D%0A%20%20G%20--%3E%20S%5B%22%E9%95%BF%E6%9C%9F%E6%96%B9%E5%B7%AE%20S%20HAC%22%5D%0A%20%20S%20--%3E%20W%5B%22%E6%9D%83%E9%87%8D%20W%3DS%E2%81%BB%C2%B9%22%5D%0A%20%20G%20--%3E%20OBJ%5B%22%E1%B8%A1'%20W%20%E1%B8%A1%22%5D%0A%20%20W%20--%3E%20OBJ%0A%20%20OBJ%20--%3E%20TH%5B%22%CE%B8%CC%82%20GMM%22%5D%0A%20%20OBJ%20--%3E%20J%5B%22%E8%BF%87%E5%BA%A6%E8%AF%86%E5%88%AB%20J%20%E6%A3%80%E9%AA%8C%22%5D%0A%20%20J%20--%3E%20REJ%7B%22%E7%9F%A9%E6%88%90%E7%AB%8B%3F%22%7D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Hansen GMM 用正交条件同时做估计与过度识别检验；最优权重是得分的长期方差之逆。</li><li>线性因子下它统一 FM 与定价误差，GRS 是可交易因子、正态残差时的有限样本亲戚。</li><li>\\(S\\) 不稳、弱识别、用自家排序组合当矩，都会让 \\(J\\) 失去意义。</li><li>恰好识别时 GMM 退回 OLS+HAC；价值在额外资产提供的检验。</li><li>出处：Hansen, <em>Econometrica</em>, 1982；欧拉应用见 Hansen and Singleton, <em>Econometrica</em>, 1982；资产定价教科书表述见 Cochrane。</li></ul>',2))])}const u=o(d,[["render",M]]);export{b as __pageData,u as default};
